const info = await browser.js(`(() => {
  const all = Array.from(document.querySelectorAll('*'));
  const dateRegex = /\\b(January|February|March|April|May|June|July|August|September|October|November|December)\\s+\\d{1,2},?\\s+\\d{4}\\b/i;
  const matches = [];
  for (const el of all) {
    if (el.children.length === 0 && dateRegex.test(el.textContent) && el.textContent.trim().length < 40) {
      const rect = el.getBoundingClientRect();
      matches.push({ text: el.textContent.trim(), top: rect.top, bottom: rect.bottom });
    }
  }
  return matches;
})()`);
return info;

const info = await browser.js(`(() => {
  const all = Array.from(document.querySelectorAll('*'));
  const results = [];
  for (const el of all) {
    if (el.children.length === 0 && el.textContent.trim().length > 0 && el.textContent.trim().length < 60) {
      const rect = el.getBoundingClientRect();
      if (rect.top > 200 && rect.top < 1400) {
        results.push({text: el.textContent.trim(), top: Math.round(rect.top)});
      }
    }
  }
  return results;
})()`);
return info;

// close any modal/overlay
const closed = await browser.js(`(() => {
  const closeButtons = Array.from(document.querySelectorAll('button, [role="button"], svg, span'));
